#include <stdio.h>

int main(void) {
    int *p = NULL;     /* root cause: p points at address 0 */
    printf("about to read through a null pointer...\n");
    *p=5;
    int x = *p;        /* <-- THE BUG: dereference of NULL */
    printf("x = %d\n", x);
    return 0;
}

/* (no headers needed — this bug is pure pointer plumbing) */

__attribute__((noinline)) static char *writer(void) {
    char *keep = (char *)&keep;   /* leave an ASLR-randomized stack address... */
    return keep;
}

__attribute__((noinline)) static char *reader(void) {
    char *keep;                   /* ROOT CAUSE: never initialized */
    return keep;                  /* ...reads the slot writer() dirtied */
}

int main(void) {
    writer();
    char *p = reader();           /* p = a wild (uninitialized) pointer value */
#ifdef FORCE_CRASH
    p = p + (16 << 20);           /* push 16 MiB past the stack -> unmapped */
#endif
    unsigned char v = *(unsigned char *)p;  /* <-- THE BUG: deref wild pointer */
    return v;
}

#include <stdio.h>

int main(int argc, char **argv) {
    int a = 100;
    int b = argc - 1;                 /* 0 when run with no extra args */
    printf("computing %d / %d ...\n", a, b);
    int q = a / b;                    /* <-- THE BUG: divide by zero */
    printf("q = %d\n", q);
    (void)argv;
    return 0;
}

blocks.text:
Guard the divisor:
    if (b == 0) { fprintf(stderr, "denominator is zero\n"); return 1; }
    int q = a / b;

