#include <stdio.h>

int main(void) {
    int buf[4];                       /* valid indices: 0..3 */
    for (int i = 0; i <= 8; i++)      /* bound is wrong: i reaches 8 */
        buf[i] = i;                   /* <-- THE BUG: OOB stack write for i>=4 */
    printf("buf[0]=%d (looks fine?!)\n", buf[0]);
    return 0;
}

blocks.text:
Use a correct bound (strictly < the element count):
    for (int i = 0; i < 4; i++) buf[i] = i;
Or size the loop from the array: `for (i=0; i < (int)(sizeof buf/sizeof buf[0]); i++)`.

