#include <stdlib.h>
#include <stdio.h>

int main(void) {
    char *p = malloc(8);              /* 8 bytes: valid p[0..7] */
    p[0] = 'o';
    p[7] = 'k';
    p[8] = '!';                       /* <-- THE BUG: write 1 byte past block */
    printf("stored, p[7]=%c\n", p[7]);
    free(p);
    return 0;
}

#include <stdlib.h>
#include <stdio.h>

int main(void) {
    int *p = malloc(sizeof(int));     /* allocate one int */
    *p = 42;
    free(p);                          /* block returned to the allocator */
    int x = *p;                       /* <-- THE BUG: read through freed ptr */
    printf("x = %d\n", x);
    return 0;
}

#include <stdlib.h>
#include <stdio.h>

int main(void) {
    int *p = malloc(sizeof(int));     /* allocate one int */
    free(p);                          /* first free: legitimate */
    printf("first free done\n");
    free(p);                          /* <-- THE BUG: second free of same ptr */
    return 0;
}

#include <stdlib.h>
#include <stdio.h>

int main(void) {
    char *p = malloc(100);            /* <-- THE BUG: never freed */
    p[0] = 0x55;
    printf("used p[0]=0x%02x; now leaking 100 bytes\n", (unsigned char)p[0]);
    return 0;                         /* p lost here: 100 bytes leak */
}

blocks.text:
Free what you allocate, on every path:
    free(p);
(For CI, see --error-exitcode in the README so a leak fails the build.)

