#include <stdio.h>

int main(void) {
    int x;                            /* ROOT CAUSE: never initialized */
    if (x > 42)                       /* <-- THE BUG: branch on uninitialized x */
        printf("x is big\n");
    return x & 1;                     /* also feeds undefined bits to exit() */
}

#include <stdio.h>

__attribute__((noinline)) static int *get_ptr(void) {
    int local = 42;                   /* lives only for this call */
    return &local;                    /* <-- THE BUG: address of a dead local */
}

int main(void) {
    int *p = get_ptr();               /* p now dangles into a freed frame */
    printf("*p (first read) = %d\n", *p);   /* deref dangling pointer */
    return *p & 0xff;                 /* read again: slot may be reused now */
}

static int recurse(int depth) {
    return recurse(depth + 1) + 1;    /* <-- THE BUG: no base case ever stops it */
}

int main(void) {
    return recurse(0);
}

blocks.text:
Give the recursion a base case that is always reached:
    int recurse(int depth) {
        if (depth >= LIMIT) return 0;     // base case
        return recurse(depth + 1) + 1;
    }
Or rewrite as an explicit loop with bounded iterations.

