#include <limits.h>
#include <stdio.h>

int main(int argc, char **argv) {
    int x = INT_MAX;
    int y = x + argc;                 /* <-- THE BUG: INT_MAX + (argc>=1) overflows */
    printf("y = %d\n", y);
    (void)argv;
    return 0;
}

blocks.text:
Check before the operation, or use a wider/unsigned type deliberately:
    if (x > INT_MAX - argc) { ...handle the overflow... }
    long y = (long)x + argc;            // compute in a wider type

