#include <stdio.h>

typedef void (*fn_t)(void);

int main(void) {
    fn_t f = NULL;                    /* null function pointer */
    printf("calling through a null function pointer...\n");
    f();                              /* <-- THE BUG: call via NULL */
    return 0;
}

#include <stdlib.h>
#include <stdio.h>

int main(void) {
    int n = 5;
    int *a = malloc(n * sizeof(int));     /* 5 ints: valid a[0..4] */
    for (int i = 0; i < n; i++)
        a[i] = i;
    int sum = 0;
    for (int i = 0; i <= n; i++)          /* <-- THE BUG: i<=n reads a[5] */
        sum += a[i];                      /* OOB read when i==n */
    printf("sum = %d\n", sum);
    free(a);
    return 0;
}

#include <stdlib.h>

int main(void) {
    int x = 42;
    int *p = &x;                      /* p points at a STACK variable */
    free(p);                          /* <-- THE BUG: free() of a non-heap ptr */
    return 0;
}

#include <vector>
#include <iostream>
#include <cstdlib>

static void demo_index(void) {            /* DEMO 1: operator[] OOB */
    std::vector<int> v{10, 20, 30};       /* size 3, valid indices 0..2 */
    std::cout << "v[5] = " << v[5] << "\n";   /* <-- BUG: unchecked OOB (UB) */
}

static void demo_at(void) {               /* DEMO 2: at() OOB (checked) */
    std::vector<int> v{10, 20, 30};
    std::cout << "v.at(5) = " << v.at(5) << "\n";  /* <-- throws out_of_range */
}

static void demo_uaf(void) {              /* DEMO 3: new/delete use-after-free */
    int *p = new int(42);
    delete p;                             /* freed here (p left dangling) */
    std::cout << "*p after delete = " << *p << "\n";  /* <-- BUG: use-after-free */
}

static void demo_delete_mismatch(void) {  /* DEMO 4: delete vs delete[] */
    int *arr = new int[8];                /* array-new */
    arr[0] = 1;
    delete arr;                           /* <-- BUG: must be delete[] arr */
    std::cout << "deleted (mismatched)\n";
}

int main(int argc, char **argv) {
    int which = (argc > 1) ? std::atoi(argv[1]) : 1;
    switch (which) {
        case 1: demo_index(); break;
        case 2: demo_at(); break;
        case 3: demo_uaf(); break;
        case 4: demo_delete_mismatch(); break;
        default: std::cout << "pass 1..4\n";
    }
    return 0;
}

int deref_and_store(int *p) {
    *p = 42;            /* faults here when p == NULL */
    return *p;
}
int main(void) {
    int *p = 0;         /* null pointer */
    return deref_and_store(p);
}

int store_through(int *p) {
    *p = 0xABCD;        /* THE faulting operation: store 0xABCD through p (p==NULL) */
    return *p;
}

int main(void) {
    int *p = 0;         /* null pointer */
    return store_through(p);
}

int compute(int *p, int a, int b) {
    int x = a + b;      /* a few real operations, so the store's ordinal is large */
    int y = x * a;
    int z = y - b;
    int w = z + x;
    *p = w;             /* THE faulting store (p == NULL) */
    return w;
}

int main(void) {
    int *p = 0;
    return compute(p, 3, 4);
}

int crash_after_math(int *p, int a, int b) {
    int scaled = a * b + 7;     /* real local at -O0; constant-folded away at -O2 */
    *p = scaled;                /* faults when p == NULL */
    return scaled;
}

int main(void) {
    int *p = 0;
    return crash_after_math(p, 6, 7);   /* scaled = 6*7+7 = 49 */
}

#include "../tools/bench.h"

/* A dependent chain: iteration i+1 cannot start before iteration i finishes. */
static uint64_t work(uint64_t n) {
    uint64_t x = 1;
    for (uint64_t i = 0; i < n; i++) {
        x = x * 6364136223846793005ull + 1442695040888963407ull;
        x ^= x >> 29;
    }
    return x;
}

int main(int argc, char **argv) {
    uint64_t n = argc > 1 ? strtoull(argv[1], 0, 10) : 10000000ull;   /* ~29 ms on a P-core */
    int reps  = argc > 2 ? atoi(argv[2]) : 30;
    uint64_t *s = (uint64_t *)malloc((size_t)reps * sizeof *s);
    int start_cpu = bench_cpu(), migrated = 0;

    for (int r = 0; r < reps; r++) {
        int c = bench_cpu();
        uint64_t t0 = bench_ns();
        uint64_t x = work(n);
        BENCH_KEEP(x);                                /* never let the loop be deleted */
        s[r] = (bench_ns() - t0) / 1000;              /* microseconds */
        if (bench_cpu() != c) migrated++;
    }

    printf("work(%llu) x %d reps | started on CPU %d | %d reps changed CPU mid-run\n",
           (unsigned long long)n, reps, start_cpu, migrated);
    printf("first 5 reps (us): %llu %llu %llu %llu %llu   <- watch the frequency ramp\n",
           (unsigned long long)s[0], (unsigned long long)s[1], (unsigned long long)s[2],
           (unsigned long long)s[3], (unsigned long long)s[4]);
    bench_stats st = bench_compute(s, (uint64_t)reps);
    bench_print_header("us");
    bench_print("dependent_chain", &st);
    printf("spread max/min = %.2fx   p99/p50 = %.2fx   ns/iter at min = %.2f\n",
           (double)st.max / (double)st.min, (double)st.p99 / (double)st.p50,
           (double)st.min * 1000.0 / (double)n);
    free(s);
    return 0;
}

#include "../tools/bench.h"

#define BRANCH_N   (1u << 24)          /* 16M bytes */
#define STRIDE_N   (1u << 24)          /* 16M ints = 64 MB, far bigger than L3 */
#define STRIDE     16                  /* 16 ints = 64 bytes = one cache line */

/* Sum values >= 128 with a REAL branch: the asm barrier inside the taken path
 * stops clang from if-converting (cmov) or vectorizing it. */
static uint64_t branch_sum(const unsigned char *a, size_t n) {
    uint64_t sum = 0;
    for (size_t i = 0; i < n; i++) {
        if (a[i] >= 128) { sum += a[i]; __asm__ __volatile__("" ::: "memory"); }
    }
    return sum;
}

static uint64_t stride_sum(const int *a, size_t n, size_t stride) {
    uint64_t sum = 0;
    for (size_t i = 0; i < n; i += stride) sum += (uint64_t)a[i];
    return sum;
}

/* O(n) counting sort: qsort on 16M bytes takes seconds and would swamp the
 * counters (perf stat counts the WHOLE process, setup included). */
static void counting_sort(unsigned char *a, size_t n) {
    size_t cnt[256] = {0};
    for (size_t i = 0; i < n; i++) cnt[a[i]]++;
    size_t k = 0;
    for (int v = 0; v < 256; v++) while (cnt[v]--) a[k++] = (unsigned char)v;
}

int main(int argc, char **argv) {
    const char *mode = argc > 1 ? argv[1] : "branch-random";
    int passes = argc > 2 ? atoi(argv[2]) : 10;   /* long enough that setup is <5% of counts */
    uint64_t seed = 0x9E3779B97F4A7C15ull, result = 0, t0, t1;

    if (!strncmp(mode, "branch", 6)) {
        unsigned char *a = (unsigned char *)malloc(BRANCH_N);
        for (size_t i = 0; i < BRANCH_N; i++) a[i] = (unsigned char)(bench_rand(&seed) >> 56);
        if (!strcmp(mode, "branch-sorted")) counting_sort(a, BRANCH_N);
        t0 = bench_ns();
        for (int p = 0; p < passes; p++) result += branch_sum(a, BRANCH_N);
        t1 = bench_ns();
        free(a);
    } else if (!strncmp(mode, "stride", 6)) {
        size_t stride = !strcmp(mode, "stride-16") ? STRIDE : 1;
        int *a = (int *)malloc(STRIDE_N * sizeof *a);
        for (size_t i = 0; i < STRIDE_N; i++) a[i] = (int)(i & 0xFF);          /* cheap fill */
        t0 = bench_ns();
        for (int p = 0; p < passes; p++) result += stride_sum(a, STRIDE_N, stride);
        t1 = bench_ns();
        free(a);
    } else {
        fprintf(stderr, "usage: %s branch-sorted|branch-random|stride-1|stride-16 [passes]\n", argv[0]);
        return 2;
    }
    BENCH_KEEP(result);
    printf("%-14s %3d passes  %8.2f ms   (cpu %d)\n", mode, passes, (double)(t1 - t0) / 1e6, bench_cpu());
    return 0;
}

#include <cstdint>
#include <cstdio>
#include <cstring>
#include <string>
#include <vector>

/* HOT: tiny, called per line, inlined at -O2. No out-of-line copy exists. */
static inline uint32_t fnv1a(const char *p, size_t n) {
    uint32_t h = 2166136261u;
    for (size_t i = 0; i < n; i++) {
        h ^= (unsigned char)p[i];
        h *= 16777619u;
    }
    return h;
}

/* MEDIUM: touched once per line, but only a few bytes. External linkage, so an
 * out-of-line (mangled) copy exists in the binary for STEP 4. */
uint32_t normalize(const std::string &line) {
    uint32_t v = 0;
    for (size_t i = 0; i < line.size() && i < 8; i++) v = v * 10 + (line[i] & 15);
    return v;
}

/* COLD: once per pass. */
static void format_summary(char *out, size_t n, uint32_t h, uint64_t cnt) {
    snprintf(out, n, "hash=%08x odd=%llu", h, (unsigned long long)cnt);
}

/* The caller that "owns" the samples once fnv1a is inlined. */
static uint64_t process(const std::vector<std::string> &lines, uint32_t *hash_out) {
    uint32_t h = 0; uint64_t odd = 0;
    for (const std::string &l : lines) {
        h ^= fnv1a(l.data(), l.size());
        odd += normalize(l) & 1;
    }
    *hash_out = h;
    return odd;
}

int main(int argc, char **argv) {
    int passes = argc > 1 ? atoi(argv[1]) : 30;
    std::vector<std::string> lines;
    lines.reserve(200000);
    for (int i = 0; i < 200000; i++) {
        char buf[96];
        snprintf(buf, sizeof buf, "%08d,host%02d,GET /api/v1/items/%d?q=%x,200,%d",
                 i, i % 37, i * 7919, i * 2654435761u, 100 + (i % 900));
        lines.emplace_back(buf);
    }
    uint32_t h = 0; uint64_t odd = 0;
    char summary[64];
    for (int p = 0; p < passes; p++) {
        odd += process(lines, &h);
        format_summary(summary, sizeof summary, h, odd);
    }
    printf("%d passes over %zu lines: %s\n", passes, lines.size(), summary);
    return 0;
}

#include "../tools/bench.h"

/* The honest kernel: sum an int array. At -O2 clang vectorizes it (SSE2 at
 * the baseline x86-64 target), so the real cost is memory bandwidth. */
__attribute__((noinline)) static uint64_t sum_keep(const int *a, size_t n) {
    uint64_t s = 0;
    for (size_t i = 0; i < n; i++) s += (uint64_t)a[i];
    return s;
}

/* PITFALL dce: same loop, result thrown away -> the loop is deleted. The
 * function still exists (it returns the last element, which the caller
 * cannot compute without calling it), but its body has no loop. */
__attribute__((noinline)) static uint64_t sum_dce(const int *a, size_t n) {
    uint64_t s = 0;
    for (size_t i = 0; i < n; i++) s += (uint64_t)a[i];
    return (uint64_t)a[n - 1];                   /* <-- s unused: the loop is dead */
}

/* PITFALL constfold: a loop whose result the compiler can compute itself.
 * LLVM's scalar evolution (SCEV) knows sum(i*i) has a closed form; with a
 * constant N the answer is a literal, and even with an OPAQUE n there is no
 * loop, just a polynomial. */
__attribute__((noinline)) static uint64_t sum_squares(uint64_t n) {
    uint64_t s = 0;
    for (uint64_t i = 0; i < n; i++) s += i * i;
    return s;
}
static inline uint64_t sum_squares_inl(uint64_t n) {   /* inlinable copy */
    uint64_t s = 0;
    for (uint64_t i = 0; i < n; i++) s += i * i;
    return s;
}
__attribute__((noinline)) static uint64_t sum_squares_const(void) {
    return sum_squares_inl(1000);                /* <-- folded to a literal at build time */
}

/* PITFALL volatile: the "fix" that measures a different program. The
 * volatile accumulator forces a load+store per element and forbids
 * vectorization: 8x slower than the code you actually ship. */
__attribute__((noinline)) static uint64_t sum_volatile(const int *a, size_t n) {
    volatile uint64_t s = 0;
    for (size_t i = 0; i < n; i++) s += (uint64_t)a[i];   /* <-- store every iteration */
    return s;
}

static void row(const char *name, uint64_t ns, uint64_t n, const char *note) {
    printf("%-10s %12.3f ms  %8.3f ns/iter   %s\n", name, (double)ns / 1e6, (double)ns / (double)n, note);
}

int main(int argc, char **argv) {
    const char *mode = argc > 1 ? argv[1] : "all";
    size_t n = argc > 2 ? strtoull(argv[2], 0, 10) : (64u << 20);    /* 64M ints = 256 MB, opaque */
    int all = !strcmp(mode, "all");
    uint64_t t0, r;

    int *a = (int *)malloc(n * sizeof *a);
    for (size_t i = 0; i < n; i++) a[i] = (int)(i & 0xFF);            /* also pre-faults the pages */

    if (all || !strcmp(mode, "dce")) {
        t0 = bench_ns(); r = sum_dce(a, n); BENCH_KEEP(r);
        row("dce", bench_ns() - t0, n, "sum unused -> loop deleted");
    }
    if (all || !strcmp(mode, "constfold")) {
        t0 = bench_ns(); r = sum_squares_const(); BENCH_KEEP(r);
        row("constfold", bench_ns() - t0, 1000, "constant input -> answer computed at build time");
        t0 = bench_ns(); r = sum_squares(n); BENCH_KEEP(r);
        row("closedform", bench_ns() - t0, n, "opaque input, but SCEV replaced the loop by a formula");
    }
    if (all || !strcmp(mode, "keep")) {
        t0 = bench_ns(); r = sum_keep(a, n); BENCH_KEEP(r);
        row("keep", bench_ns() - t0, n, "opaque input + BENCH_KEEP -> real (vectorized) number");
    }
    if (all || !strcmp(mode, "volatile")) {
        t0 = bench_ns(); r = sum_volatile(a, n); BENCH_KEEP(r);
        row("volatile", bench_ns() - t0, n, "volatile accumulator -> measures the harness");
    }
    if (all || !strcmp(mode, "warmup")) {
        size_t bytes = 256ull << 20;
        unsigned char *buf = (unsigned char *)malloc(bytes);
        for (int pass = 1; pass <= 2; pass++) {
            t0 = bench_ns();
            for (size_t i = 0; i < bytes; i += 64) buf[i] = (unsigned char)i;
            BENCH_KEEP(buf);
            char note[64]; snprintf(note, sizeof note, "pass %d over 256 MB, one write per line", pass);
            row(pass == 1 ? "warmup-1" : "warmup-2", bench_ns() - t0, bytes / 64, note);
        }
        free(buf);
    }
    if (all || !strcmp(mode, "timer")) {
        uint64_t reps = 10000000, acc = 0;
        t0 = bench_ns(); for (uint64_t i = 0; i < reps; i++) acc += bench_ns(); BENCH_KEEP(acc);
        row("timer-ns", bench_ns() - t0, reps, "cost of one clock_gettime (vDSO)");
        t0 = bench_ns(); for (uint64_t i = 0; i < reps; i++) acc += bench_tsc(); BENCH_KEEP(acc);
        row("timer-tsc", bench_ns() - t0, reps, "cost of one rdtsc");
        t0 = bench_ns(); for (uint64_t i = 0; i < reps; i++) acc += bench_tsc_end(); BENCH_KEEP(acc);
        row("timer-tscp", bench_ns() - t0, reps, "cost of one rdtscp+lfence (serialized)");
        printf("tsc rate: %.3f GHz (calibrated against CLOCK_MONOTONIC)\n", bench_tsc_hz() / 1e9);
    }
    free(a);
    return 0;
}

#include "../tools/bench.h"
#include <sys/mman.h>
#include <sys/resource.h>

#define TABLE_BYTES   (64ull << 20)
#define TABLE_N       (TABLE_BYTES / sizeof(uint32_t))
#define CHAIN         8

static long read_status_field(const char *key) {   /* from /proc/self/status */
    FILE *f = fopen("/proc/self/status", "r"); if (!f) return -1;
    char line[256]; long v = -1;
    while (fgets(line, sizeof line, f))
        if (!strncmp(line, key, strlen(key))) { v = atol(line + strlen(key)); break; }
    fclose(f); return v;
}
static long minflt(void) { struct rusage r; getrusage(RUSAGE_SELF, &r); return r.ru_minflt; }

int main(int argc, char **argv) {
    const char *mode = argc > 1 ? argv[1] : "cold";
    uint64_t iters = argc > 2 ? strtoull(argv[2], 0, 10) : 1000000ull;
    uint32_t *table;

    if (!strcmp(mode, "populate")) {
        table = (uint32_t *)mmap(NULL, TABLE_BYTES, PROT_READ | PROT_WRITE,
                                 MAP_PRIVATE | MAP_ANONYMOUS | MAP_POPULATE, -1, 0);
        if (table == MAP_FAILED) { perror("mmap"); return 1; }
    } else {
        table = (uint32_t *)calloc(TABLE_N, sizeof *table);    /* fresh zero pages, untouched */
        if (!table) { perror("calloc"); return 1; }
    }
    if (!strcmp(mode, "warm")) {
        for (size_t i = 0; i < TABLE_N; i += 1024) table[i] = 1;   /* one write per 4 KiB page */
        BENCH_CLOBBER();
    }
    /* The samples array is 8 MB: touch it NOW so its own page faults do not
     * land inside the timed loop. Two real bugs from drafts of this lab:
     *  (1) not touching it at all -> ~2000 faults inside the loop;
     *  (2) memset(...,0,...) right after malloc -> clang rewrote the pair as
     *      calloc(), which touches nothing. Hence the 0xFF. */
    uint64_t *samples = (uint64_t *)malloc(iters * sizeof *samples);
    memset(samples, 0xFF, iters * sizeof *samples);
    double hz = bench_tsc_hz();
    uint64_t seed = 0xD1B54A32D192ED03ull, sink = 0;
    long flt0 = minflt(), vcs0 = read_status_field("voluntary_ctxt_switches:"),
         ics0 = read_status_field("nonvoluntary_ctxt_switches:");
    int cpu0 = bench_cpu(), migrations = 0;

    for (uint64_t it = 0; it < iters; it++) {
        uint64_t idx = bench_rand(&seed) % TABLE_N;
        uint64_t t0 = bench_tsc_begin();
        for (int k = 0; k < CHAIN; k++) {
            uint32_t v = table[idx];
            table[idx] = v + 1;                  /* a WRITE: an untouched page must really be allocated */
            idx = (idx + v + 0x9E3779B1ull * (uint64_t)(k + 1)) % TABLE_N;   /* next address depends on v */
        }
        uint64_t t1 = bench_tsc_end();
        sink += idx;
        samples[it] = (uint64_t)((double)(t1 - t0) * 1e9 / hz);
        if ((it & 0xFFFF) == 0 && bench_cpu() != cpu0) { migrations++; cpu0 = bench_cpu(); }
    }
    BENCH_KEEP(sink);
    long flt1 = minflt(), vcs1 = read_status_field("voluntary_ctxt_switches:"),
         ics1 = read_status_field("nonvoluntary_ctxt_switches:");

    printf("mode=%s iters=%llu chain=%d table=%llu MB  (ending on cpu %d)\n", mode,
           (unsigned long long)iters, CHAIN, (unsigned long long)(TABLE_BYTES >> 20), bench_cpu());
    bench_stats st = bench_compute(samples, iters);
    bench_print_header("ns");
    bench_print("8 dependent loads", &st);
    printf("tail: p99/p50 = %.1fx   p99.9/p50 = %.1fx   max/p50 = %.0fx\n",
           (double)st.p99 / (double)st.p50, (double)st.p999 / (double)st.p50, (double)st.max / (double)st.p50);
    printf("during loop: minor page faults=%ld  voluntary ctxsw=%ld  involuntary ctxsw=%ld  migrations seen=%d\n",
           flt1 - flt0, vcs1 - vcs0, ics1 - ics0, migrations);
    bench_hist_log2(samples, iters, "ns");
    free(samples);
    return 0;
}

