#include "../tools/bench.h"
/* Build a random cyclic permutation over n 8-byte slots (Sattolo), then follow it. */
static void sattolo(uint64_t *p, size_t n, uint64_t *seed) {
    for (size_t i = 0; i < n; i++) p[i] = i;
    for (size_t i = n - 1; i > 0; i--) {
        size_t j = (size_t)(bench_rand(seed) % i);          /* j < i: guarantees ONE cycle */
        uint64_t t = p[i]; p[i] = p[j]; p[j] = t;
    }
}
int main(int argc, char **argv) {
    uint64_t loads = argc > 1 ? strtoull(argv[1], 0, 10) : 20000000ull;
    uint64_t seed = 0x1234567ull;
    printf("%10s %8s %10s   %s\n", "bytes", "slots", "ns/load", "P-core: L1d 48K, L2 1.25M, L3 18M (shared); dTLB ~96 entries, STLB 2048 = 8 MB reach");
    for (size_t bytes = 4096; bytes <= (512ull << 20); bytes *= 2) {
        size_t n = bytes / 8;
        uint64_t *p = (uint64_t *)malloc(bytes);
        sattolo(p, n, &seed);
        uint64_t idx = 0;
        for (uint64_t i = 0; i < n; i++) idx = p[idx];                /* warm the chain once */
        uint64_t t0 = bench_ns();
        for (uint64_t i = 0; i < loads; i++) idx = p[idx];
        uint64_t dt = bench_ns() - t0;
        BENCH_KEEP(idx);
        double ns = (double)dt / (double)loads;
        const char *lvl = bytes <= 49152 ? "L1" : bytes <= (1280u << 10) ? "L2" : bytes <= (8u << 20) ? "L3" : bytes <= (18u << 20) ? "L3 + page walks (beyond STLB reach)" : "DRAM + page walks";
        printf("%10zu %8zu %10.2f   %s\n", bytes, n, ns, lvl);
        free(p);
    }
    return 0;
}

