__attribute__((noinline)) static uint64_t soa_touch_all(Book *b, size_t n) { uint64_t s = 0; for (size_t i = 0; i < n; i++) { b->qty[i] += 1; b->price[i] *= 1.0001; s += b->id[i] ^ b->side[i]; } return s; }
__attribute__((noinline)) static uint64_t aos_random(const Order *o, const uint32_t *ix, size_t n) { uint64_t s = 0; for (size_t i = 0; i < n; i++) { const Order *r = &o[ix[i]]; s += r->id + (uint64_t)r->qty + (uint64_t)r->side + (uint64_t)r->price; } return s; }
