#include "../tools/bench.h"
#include <pthread.h>
#include <stdatomic.h>
#include <stdalign.h>
#define ITERS 100000000ull
typedef struct { atomic_uint_fast64_t v; } Plain;                                  /* 8 bytes: 8 of these share a line */
typedef struct { alignas(64) atomic_uint_fast64_t v; char pad[56]; } Padded;      /* one per line */
typedef struct { atomic_uint_fast64_t *ctr; int cpu; } Arg;
static void *worker(void *p) {
    Arg *a = (Arg *)p; bench_pin(a->cpu);
    for (uint64_t i = 0; i < ITERS; i++) atomic_fetch_add_explicit(a->ctr, 1, memory_order_relaxed);
    return NULL;
}
static double run(atomic_uint_fast64_t **ctrs, const int *cpus, int nthreads) {
    pthread_t th[8]; Arg args[8];
    uint64_t t0 = bench_ns();
    for (int i = 0; i < nthreads; i++) { args[i].ctr = ctrs[i]; args[i].cpu = cpus[i]; pthread_create(&th[i], NULL, worker, &args[i]); }
    for (int i = 0; i < nthreads; i++) pthread_join(th[i], NULL);
    return (double)(bench_ns() - t0) / 1e6;
}
int main(void) {
    static Plain plain[8]; static Padded padded[8]; static atomic_uint_fast64_t shared;
    const int cpus[4] = {2, 4, 6, 0};                    /* four different P-cores (siblings are 2-3, 4-5, 6-7, 0-1) */
    atomic_uint_fast64_t *c[4];
    printf("%-38s %10s %12s\n", "configuration", "ms", "ns/increment");
    c[0] = &plain[0].v;
    double ms1 = run(c, cpus, 1); printf("%-38s %10.1f %12.2f\n", "1 thread, own counter (baseline)", ms1, ms1 * 1e6 / ITERS);
    for (int n = 2; n <= 4; n += 2) {
        for (int i = 0; i < n; i++) c[i] = &plain[i].v;
        double ms = run(c, cpus, n); printf("%-38s %10.1f %12.2f\n", n == 2 ? "2 threads, adjacent counters (FALSE)" : "4 threads, adjacent counters (FALSE)", ms, ms * 1e6 / ITERS);
        for (int i = 0; i < n; i++) c[i] = &padded[i].v;
        ms = run(c, cpus, n); printf("%-38s %10.1f %12.2f\n", n == 2 ? "2 threads, padded counters" : "4 threads, padded counters", ms, ms * 1e6 / ITERS);
        for (int i = 0; i < n; i++) c[i] = &shared;
        ms = run(c, cpus, n); printf("%-38s %10.1f %12.2f\n", n == 2 ? "2 threads, SAME counter (true sharing)" : "4 threads, SAME counter (true sharing)", ms, ms * 1e6 / ITERS);
    }
    printf("sizeof(Plain)=%zu sizeof(Padded)=%zu  &plain[1]-&plain[0]=%td bytes\n", sizeof(Plain), sizeof(Padded), (char *)&plain[1] - (char *)&plain[0]);
    return 0;
}

#include "../tools/bench.h"
#define BYTES (128ull << 20)
#define NODES (BYTES / 16)                          /* node = {next, ahead}: 16 bytes, both in one line */
static void sattolo(uint64_t *nxt, size_t n, uint64_t *seed) {
    for (size_t i = 0; i < n; i++) nxt[i] = i;
    for (size_t i = n - 1; i > 0; i--) { size_t j = (size_t)(bench_rand(seed) % i); uint64_t t = nxt[i]; nxt[i] = nxt[j]; nxt[j] = t; }
}
/* K independent chains started at K different points of the same cycle. */
__attribute__((noinline)) static uint64_t chase(const uint64_t *p, int k, uint64_t steps) {
    uint64_t idx[16]; for (int c = 0; c < k; c++) idx[c] = (uint64_t)c * (NODES / 17);
    for (uint64_t s = 0; s < steps; s++) for (int c = 0; c < k; c++) idx[c] = p[2 * idx[c]];
    uint64_t r = 0; for (int c = 0; c < k; c++) r += idx[c]; return r;
}
/* ONE chain, but each node also stores the node D steps ahead ("jump pointer"), so we can prefetch it. */
__attribute__((noinline)) static uint64_t chase_jump(const uint64_t *p, uint64_t steps, int use_prefetch) {
    uint64_t idx = 0;
    for (uint64_t s = 0; s < steps; s++) {
        if (use_prefetch) __builtin_prefetch(&p[2 * p[2 * idx + 1]], 0, 0);   /* address known NOW, needed D steps later */
        idx = p[2 * idx];
    }
    return idx;
}
/* Independent loads with addresses known in advance (an index array): does prefetch help here? */
__attribute__((noinline)) static uint64_t gather(const uint64_t *p, const uint32_t *ix, uint64_t n, int dist) {
    uint64_t s = 0;
    for (uint64_t i = 0; i < n; i++) { if (dist) __builtin_prefetch(&p[2 * ix[i + dist]], 0, 0); s += p[2 * ix[i]]; }
    return s;
}
int main(int argc, char **argv) {
    int D = argc > 1 ? atoi(argv[1]) : 8;
    uint64_t seed = 7; uint64_t *nxt = malloc(NODES * 8); sattolo(nxt, NODES, &seed);
    uint64_t *p = malloc(BYTES);                                  /* p[2i] = next, p[2i+1] = D steps ahead */
    uint64_t *order = malloc(NODES * 8);                          /* walk the cycle once to know who is D ahead */
    uint64_t cur = 0; for (uint64_t k = 0; k < NODES; k++) { order[k] = cur; cur = nxt[cur]; }
    for (uint64_t k = 0; k < NODES; k++) { uint64_t i = order[k]; p[2 * i] = nxt[i]; p[2 * i + 1] = order[(k + (uint64_t)D) % NODES]; }
    free(order); free(nxt);
    uint64_t steps = 4000000;
    printf("== 1: K independent dependent chains over 128 MB (steps per chain = %llu) ==\n", (unsigned long long)steps);
    printf("%8s %12s\n", "chains", "ns/load");
    for (int k = 1; k <= 16; k *= 2) {
        uint64_t t0 = bench_ns(); uint64_t r = chase(p, k, steps); BENCH_KEEP(r);
        printf("%8d %12.1f\n", k, (double)(bench_ns() - t0) / (double)(steps * (uint64_t)k));
    }
    printf("\n== 2: ONE chain with jump pointers (D=%d): prefetch the node D steps ahead ==\n", D);
    uint64_t t0 = bench_ns(); uint64_t r = chase_jump(p, steps, 0); BENCH_KEEP(r);
    printf("%-22s %8.1f ns/load\n", "no prefetch", (double)(bench_ns() - t0) / (double)steps);
    t0 = bench_ns(); r = chase_jump(p, steps, 1); BENCH_KEEP(r);
    printf("%-22s %8.1f ns/load\n", "prefetch(ahead)", (double)(bench_ns() - t0) / (double)steps);
    uint64_t n = 8000000; uint32_t *ix = malloc((n + 64) * 4);
    for (uint64_t i = 0; i < n + 64; i++) ix[i] = (uint32_t)(bench_rand(&seed) % NODES);
    printf("\n== 3: independent loads with addresses in an index array: prefetch distance ==\n");
    printf("%9s %12s\n", "distance", "ns/load");
    int dists[] = {0, 4, 16, 64};
    for (size_t d = 0; d < sizeof dists / sizeof *dists; d++) {
        t0 = bench_ns(); r = gather(p, ix, n, dists[d]); BENCH_KEEP(r);
        printf("%9d %12.1f\n", dists[d], (double)(bench_ns() - t0) / (double)n);
    }
    return 0;
}

#include "../tools/bench.h"
#include <sys/mman.h>
#include <errno.h>
#ifndef MADV_COLLAPSE
#define MADV_COLLAPSE 25                        /* Linux 6.1+: synchronously collapse into huge pages */
#endif
static long anon_huge_kb(void) {                 /* sum of AnonHugePages over /proc/self/smaps */
    FILE *f = fopen("/proc/self/smaps", "r"); if (!f) return -1;
    char line[256]; long kb = 0;
    while (fgets(line, sizeof line, f)) if (!strncmp(line, "AnonHugePages:", 14)) kb += atol(line + 14);
    fclose(f); return kb;
}
int main(int argc, char **argv) {
    const char *mode = argc > 1 ? argv[1] : "4k";
    uint64_t loads = argc > 2 ? strtoull(argv[2], 0, 10) : 5000000ull;
    uint64_t mb = argc > 3 ? strtoull(argv[3], 0, 10) : 1024;          /* region size in MB (power of two) */
    uint64_t bytes = mb << 20, slots = bytes / 8;
    uint64_t *p = mmap(NULL, bytes, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (p == MAP_FAILED) { perror("mmap"); return 1; }
    int huge = !strcmp(mode, "huge");
    madvise(p, bytes, huge ? MADV_HUGEPAGE : MADV_NOHUGEPAGE);
    for (size_t i = 0; i < slots; i += 512) p[i] = 0;            /* touch every 4 KiB page */
    long kb_fault = anon_huge_kb();
    int rc = 0;
    if (huge) { rc = madvise(p, bytes, MADV_COLLAPSE); if (rc) rc = errno; }   /* ask the kernel to finish the job */
    long kb_now = anon_huge_kb();
    /* Dependent random chain WITHOUT a permutation: the next index depends on the loaded value (all zero),
     * so the load must complete before the next address exists. */
    uint64_t seed = 99, idx = 0;
    uint64_t t0 = bench_ns();
    for (uint64_t i = 0; i < loads; i++) idx = (p[idx] + bench_rand(&seed)) & (slots - 1);
    uint64_t dt = bench_ns() - t0; BENCH_KEEP(idx);
    printf("mode=%-4s region=%llu MB  huge after fault=%ld MB, after MADV_COLLAPSE=%ld MB (rc=%d %s) | dependent random loads: %.1f ns/load\n",
           mode, (unsigned long long)mb, kb_fault / 1024, kb_now / 1024, rc, rc ? strerror(rc) : "ok", (double)dt / (double)loads);
    return 0;
}

