#include "../tools/bench.h"

/* 1. May alias: y and x could overlap -> clang emits a runtime overlap check (loop versioning), then vectorizes. */
void axpy(float *y, const float *x, float a, size_t n) { for (size_t i = 0; i < n; i++) y[i] = a * x[i] + y[i]; }
/* 2. restrict: no check needed. */
void axpy_restrict(float *restrict y, const float *restrict x, float a, size_t n) { for (size_t i = 0; i < n; i++) y[i] = a * x[i] + y[i]; }
/* 3. FP reduction: reordering additions changes rounding -> NOT vectorized unless allowed. */
float dot(const float *a, const float *b, size_t n) { float s = 0; for (size_t i = 0; i < n; i++) s += a[i] * b[i]; return s; }
/* 4. Same reduction, reassociation allowed for THIS function only. */
float dot_pragma(const float *a, const float *b, size_t n) {
#pragma clang fp reassociate(on)                 /* must be first in the block; applies to the whole function body */
    float s = 0;
    for (size_t i = 0; i < n; i++) s += a[i] * b[i];
    return s;
}
/* 5. Loop-carried dependence: a[i] needs a[i-1] from THIS iteration -> cannot vectorize. */
void prefix(int *a, size_t n) { for (size_t i = 1; i < n; i++) a[i] += a[i - 1]; }
/* 6. Early exit: trip count unknown up front -> vectorizer gives up (no early-exit vectorization for this shape). */
int find_neg(const int *a, size_t n) { for (size_t i = 0; i < n; i++) if (a[i] < 0) return (int)i; return -1; }
/* 7. Indirect (gather) access: legal, but is it profitable on this target? The cost model decides. */
void gather(int *out, const int *in, const int *idx, size_t n) { for (size_t i = 0; i < n; i++) out[i] = in[idx[i]]; }

int main(int argc, char **argv) {
    size_t n = argc > 1 ? strtoull(argv[1], 0, 10) : (1u << 20);   /* 1M floats = 4 MB, fits in L3 */
    float *x = malloc(n * 4), *y = malloc(n * 4);
    for (size_t i = 0; i < n; i++) { x[i] = (float)(i & 255) * 0.5f; y[i] = 1.0f; }
    int reps = 200; uint64_t t0; float r = 0;
    t0 = bench_ns(); for (int k = 0; k < reps; k++) axpy(y, x, 0.999f, n); BENCH_KEEP(y);
    printf("axpy            %8.3f ns/elem\n", (double)(bench_ns() - t0) / ((double)n * reps));
    t0 = bench_ns(); for (int k = 0; k < reps; k++) axpy_restrict(y, x, 0.999f, n); BENCH_KEEP(y);
    printf("axpy_restrict   %8.3f ns/elem\n", (double)(bench_ns() - t0) / ((double)n * reps));
    t0 = bench_ns(); for (int k = 0; k < reps; k++) r += dot(x, y, n); BENCH_KEEP(r);
    printf("dot (scalar)    %8.3f ns/elem\n", (double)(bench_ns() - t0) / ((double)n * reps));
