#include "../tools/bench.h"
/* One recurrence: each iteration's multiply depends on the previous result (latency-bound). */
__attribute__((noinline)) uint64_t chain1(const uint64_t *a, size_t n) {
    uint64_t x = 1;
    for (size_t i = 0; i < n; i++) {
        __asm__ volatile("# LLVM-MCA-BEGIN chain1" ::: "memory");
        x = x * 0x9E3779B97F4A7C15ull + a[i];
        __asm__ volatile("# LLVM-MCA-END" ::: "memory");
    }
    return x;
}
/* Four independent recurrences over interleaved elements: the same work, 4 chains in flight (throughput-bound). */
__attribute__((noinline)) uint64_t chain4(const uint64_t *a, size_t n) {
    uint64_t x0 = 1, x1 = 2, x2 = 3, x3 = 4;
    for (size_t i = 0; i + 3 < n; i += 4) {
        __asm__ volatile("# LLVM-MCA-BEGIN chain4" ::: "memory");
        x0 = x0 * 0x9E3779B97F4A7C15ull + a[i];
        x1 = x1 * 0x9E3779B97F4A7C15ull + a[i + 1];
        x2 = x2 * 0x9E3779B97F4A7C15ull + a[i + 2];
        x3 = x3 * 0x9E3779B97F4A7C15ull + a[i + 3];
        __asm__ volatile("# LLVM-MCA-END" ::: "memory");
    }
    return x0 ^ x1 ^ x2 ^ x3;
}
int main(int argc, char **argv) {
    size_t n = argc > 1 ? strtoull(argv[1], 0, 10) : (1u << 20);   /* 8 MB: L3-resident, so memory is not the bound */
    uint64_t *a = malloc(n * 8); for (size_t i = 0; i < n; i++) a[i] = i;
    int reps = 50; uint64_t t0, r;
    t0 = bench_ns(); r = 0; for (int k = 0; k < reps; k++) r ^= chain1(a, n); BENCH_KEEP(r);
    printf("chain1  %7.3f ns/elem\n", (double)(bench_ns() - t0) / ((double)n * reps));
    t0 = bench_ns(); r = 0; for (int k = 0; k < reps; k++) r ^= chain4(a, n); BENCH_KEEP(r);
    printf("chain4  %7.3f ns/elem\n", (double)(bench_ns() - t0) / ((double)n * reps));
    return 0;
}

#include "../tools/bench.h"
#define N (1u << 22)
/* Selection as most people write it. Does clang emit a branch or a cmov? (Read the asm before guessing.) */
__attribute__((noinline)) int64_t select_naive(const int *a, const int *b, const int *c, size_t n) {
    int64_t s = 0; for (size_t i = 0; i < n; i++) s += c[i] ? a[i] : b[i]; return s;
}
/* Both sides loaded unconditionally, then selected: this shape clang if-converts (and vectorizes). */
__attribute__((noinline)) int64_t select_cmov(const int *a, const int *b, const int *c, size_t n) {
    int64_t s = 0; for (size_t i = 0; i < n; i++) { int va = a[i], vb = b[i]; s += c[i] ? va : vb; } return s;
}
/* The same selection with a REAL branch, forced by an asm barrier (see lab perf/02). */
__attribute__((noinline)) int64_t select_branch(const int *a, const int *b, const int *c, size_t n) {
    int64_t s = 0;
    for (size_t i = 0; i < n; i++) { if (c[i]) { s += a[i]; __asm__ volatile("" ::: "memory"); } else s += b[i]; }
    return s;
}
/* Compaction: copy the elements that pass a test. Branchy or branchless? Read the asm. */
__attribute__((noinline)) size_t compact(int *out, const int *in, const int *keep, size_t n) {
    size_t j = 0; for (size_t i = 0; i < n; i++) { out[j] = in[i]; j += keep[i] != 0; } return j;
}
static void run(const char *label, const int *c, int *a, int *b, int *out) {
    uint64_t t0; int64_t r; size_t k;
    t0 = bench_ns(); r = select_naive(a, b, c, N); BENCH_KEEP(r);  double nv = (double)(bench_ns() - t0) / N;
    t0 = bench_ns(); r = select_cmov(a, b, c, N); BENCH_KEEP(r);   double cmov = (double)(bench_ns() - t0) / N;
    t0 = bench_ns(); r = select_branch(a, b, c, N); BENCH_KEEP(r); double br = (double)(bench_ns() - t0) / N;
    t0 = bench_ns(); k = compact(out, a, c, N); BENCH_KEEP(k);     double cp = (double)(bench_ns() - t0) / N;
    printf("%-22s naive %5.2f   cmov %5.2f   forced-branch %5.2f   compact %5.2f   (ns/elem)\n", label, nv, cmov, br, cp);
}
int main(void) {
