    uint64_t seed = 5;
    for (size_t i = 0; i < N; i++) { a[i] = (int)(i & 1023); b[i] = (int)(i & 511); c_rand[i] = (int)(bench_rand(&seed) & 1); c_pred[i] = (i & 1023) < 512; }
    for (int rep = 0; rep < 2; rep++) { run("random condition", c_rand, a, b, out); run("predictable condition", c_pred, a, b, out); }
