#include "../tools/bench.h"
#include <atomic>
#include <thread>
#include <cstring>
#ifndef CAP_LOG2
#define CAP_LOG2 12
#endif
static const size_t CAP = 1u << CAP_LOG2;                 /* slots, power of two (4096 by default) */
static const uint64_t N = 50000000;                       /* items to transfer */

/* A: "obvious" version: seq_cst everywhere, head and tail adjacent (same cache line). */
struct QueueNaive {
    std::atomic<size_t> head{0}, tail{0}; uint64_t buf[CAP];
    bool push(uint64_t v) { size_t t = tail.load(); if (t - head.load() == CAP) return false; buf[t & (CAP - 1)] = v; tail.store(t + 1); return true; }
    bool pop(uint64_t &v) { size_t h = head.load(); if (tail.load() == h) return false; v = buf[h & (CAP - 1)]; head.store(h + 1); return true; }
};
/* B: acquire/release on the shared indices, each index on its own cache line. */
struct QueuePadded {
    alignas(64) std::atomic<size_t> head{0};
    alignas(64) std::atomic<size_t> tail{0};
    alignas(64) uint64_t buf[CAP];
    bool push(uint64_t v) { size_t t = tail.load(std::memory_order_relaxed); if (t - head.load(std::memory_order_acquire) == CAP) return false; buf[t & (CAP - 1)] = v; tail.store(t + 1, std::memory_order_release); return true; }
    bool pop(uint64_t &v) { size_t h = head.load(std::memory_order_relaxed); if (tail.load(std::memory_order_acquire) == h) return false; v = buf[h & (CAP - 1)]; head.store(h + 1, std::memory_order_release); return true; }
};
/* C: B + each side keeps a private copy of the OTHER index and only re-reads the shared line when it must. */
struct QueueCached {
    alignas(64) std::atomic<size_t> head{0}; size_t tail_cache{0};    /* consumer's line: head + its copy of tail */
    alignas(64) std::atomic<size_t> tail{0}; size_t head_cache{0};    /* producer's line: tail + its copy of head */
    alignas(64) uint64_t buf[CAP];
    bool push(uint64_t v) {
        size_t t = tail.load(std::memory_order_relaxed);
        if (t - head_cache == CAP) { head_cache = head.load(std::memory_order_acquire); if (t - head_cache == CAP) return false; }
        buf[t & (CAP - 1)] = v; tail.store(t + 1, std::memory_order_release); return true;
    }
    bool pop(uint64_t &v) {
        size_t h = head.load(std::memory_order_relaxed);
        if (tail_cache == h) { tail_cache = tail.load(std::memory_order_acquire); if (tail_cache == h) return false; }
        v = buf[h & (CAP - 1)]; head.store(h + 1, std::memory_order_release); return true;
    }
};
template <class Q> static double run(const char *name, int cpu_p, int cpu_c) {
    Q *q = new Q();
    uint64_t t0 = bench_ns();
    std::thread prod([&] { bench_pin(cpu_p); for (uint64_t i = 0; i < N; i++) while (!q->push(i)) {} });
    std::thread cons([&] { bench_pin(cpu_c); uint64_t v, sum = 0; for (uint64_t i = 0; i < N; i++) { while (!q->pop(v)) {} sum += v; } BENCH_KEEP(sum); if (sum != N * (N - 1) / 2) printf("  !! %s: checksum mismatch\n", name); });
    prod.join(); cons.join();
    double ns = (double)(bench_ns() - t0) / (double)N;
    printf("%-14s %7.1f ns/item  %6.1f M items/s\n", name, ns, 1000.0 / ns);
    delete q; return ns;
}
int main(int argc, char **argv) {
    int cp = argc > 1 ? atoi(argv[1]) : 2, cc = argc > 2 ? atoi(argv[2]) : 4;   /* two different physical P-cores */
    printf("producer on CPU %d, consumer on CPU %d, %llu items, capacity %zu\n", cp, cc, (unsigned long long)N, CAP);
    run<QueueNaive>("naive", cp, cc); run<QueuePadded>("padded", cp, cc); run<QueueCached>("cached", cp, cc);
    printf("-- same physical core, two SMT threads (CPU %d and %d): --\n", cp, cp + 1);
    run<QueueCached>("cached/SMT", cp, cp + 1);
    return 0;
}

