struct Spin {                                             /* test-and-test-and-set with pause */
    std::atomic<bool> locked{false};
    void lock() { for (;;) { if (!locked.exchange(true, std::memory_order_acquire)) return; while (locked.load(std::memory_order_relaxed)) _mm_pause(); } }
    void unlock() { locked.store(false, std::memory_order_release); }
};
static std::mutex mu; static Spin sp; static std::atomic<long> at{0}; static long counter = 0;
static const long ITERS = 10000000;
static void work_mutex(long n) { for (long i = 0; i < n; i++) { std::lock_guard<std::mutex> g(mu); counter++; } }
static void work_spin(long n)  { for (long i = 0; i < n; i++) { sp.lock(); counter++; sp.unlock(); } }
static void work_atomic(long n){ for (long i = 0; i < n; i++) at.fetch_add(1, std::memory_order_relaxed); }
static double run(void (*fn)(long), int nthreads) {
    const int cpus[4] = {2, 4, 6, 0};
    counter = 0; at = 0;
    uint64_t t0 = bench_ns();
    std::vector<std::thread> th;
    for (int t = 0; t < nthreads; t++) th.emplace_back([=] { bench_pin(cpus[t]); fn(ITERS / nthreads); });
    for (auto &t : th) t.join();
    return (double)(bench_ns() - t0) / (double)ITERS;      /* ns per critical section, total */
}
int main(int argc, char **argv) {
    const char *only = argc > 1 ? argv[1] : "all";
    struct { const char *name; void (*fn)(long); } kinds[] = { {"std::mutex", work_mutex}, {"spinlock(TTAS)", work_spin}, {"atomic add", work_atomic} };
    printf("%-16s %12s %12s %12s   (ns per critical section, %ld total)\n", "lock", "1 thread", "2 threads", "4 threads", ITERS);
    for (auto &k : kinds) {
        if (strcmp(only, "all") && strcmp(only, k.name)) continue;
        printf("%-16s %12.1f %12.1f %12.1f\n", k.name, run(k.fn, 1), run(k.fn, 2), run(k.fn, 4));
    }
    return 0;
}

#include "../tools/bench.h"
#include <atomic>
#include <thread>
/*   Thread 1: x = 1; r1 = y;        Thread 2: y = 1; r2 = x;
 *   Sequential consistency forbids r1 == r2 == 0. TSO (x86) allows it: each store sits in the
 *   core's store buffer while the load reads the other variable from cache (StoreLoad reorder). */
static std::atomic<int> x{0}, y{0};
static std::atomic<long> round_{0}, done1{0}, done2{0};   /* main announces a round; each thread reports its own completion */
static int r1, r2;
template <std::memory_order MO> static void t1(long trials) {
    for (long t = 1; t <= trials; t++) { while (round_.load(std::memory_order_acquire) != t) {} x.store(1, MO); r1 = y.load(MO); done1.store(t, std::memory_order_release); }
}
template <std::memory_order MO> static void t2(long trials) {
    for (long t = 1; t <= trials; t++) { while (round_.load(std::memory_order_acquire) != t) {} y.store(1, MO); r2 = x.load(MO); done2.store(t, std::memory_order_release); }
}
template <std::memory_order MO> static long run(const char *name, long trials) {
    long both_zero = 0; x = 0; y = 0; round_ = 0; done1 = 0; done2 = 0;
    std::thread a([&] { bench_pin(2); t1<MO>(trials); }), b([&] { bench_pin(4); t2<MO>(trials); });
    for (long t = 1; t <= trials; t++) {
        x.store(0); y.store(0);
        round_.store(t, std::memory_order_release);                                   /* start trial t */
        while (done1.load(std::memory_order_acquire) != t || done2.load(std::memory_order_acquire) != t) {}
        if (r1 == 0 && r2 == 0) both_zero++;
    }
    a.join(); b.join();
    printf("%-26s r1==r2==0 in %ld of %ld trials\n", name, both_zero, trials);
    return both_zero;
}
int main(int argc, char **argv) {
    long trials = argc > 1 ? atol(argv[1]) : 1000000;
    run<std::memory_order_relaxed>("relaxed", trials);
    run<std::memory_order_acq_rel>("acquire/release", trials);   /* store=release, load=acquire */
    run<std::memory_order_seq_cst>("seq_cst", trials);
    return 0;
}

#include "../tools/bench.h"
#include <malloc.h>
#define ITERS 200000
/* A fixed-size pool: a free list threaded through pre-allocated, pre-faulted blocks. */
typedef struct Node { struct Node *next; } Node;
static Node *pool_free; static char *pool_mem;
static void pool_init(size_t block, size_t count) {
    pool_mem = malloc(block * count); memset(pool_mem, 0, block * count);          /* pre-fault */
    for (size_t i = 0; i < count; i++) { Node *n = (Node *)(pool_mem + i * block); n->next = pool_free; pool_free = n; }
}
static inline void *pool_alloc(void) { Node *n = pool_free; pool_free = n->next; return n; }
static inline void pool_free_(void *p) { Node *n = (Node *)p; n->next = pool_free; pool_free = n; }

static void measure(const char *label, size_t bytes, int use_pool, uint64_t *samples, double hz) {
    for (int i = 0; i < ITERS; i++) {
        uint64_t t0 = bench_tsc_begin();
        void *p = use_pool ? pool_alloc() : malloc(bytes);
        ((volatile char *)p)[0] = 1;                                  /* touch: a fresh page must be faulted in */
        if (use_pool) pool_free_(p); else free(p);
        uint64_t t1 = bench_tsc_end();
        samples[i] = (uint64_t)((double)(t1 - t0) * 1e9 / hz);
    }
    bench_stats st = bench_compute(samples, ITERS);
    bench_print(label, &st);
}
int main(int argc, char **argv) {
    const char *mode = argc > 1 ? argv[1] : "all";
    uint64_t *s = malloc(ITERS * sizeof *s); memset(s, 0xFF, ITERS * sizeof *s);
    double hz = bench_tsc_hz();
    pool_init(64, 1024);
    bench_print_header("ns per alloc+touch+free");
    if (!strcmp(mode, "all") || !strcmp(mode, "small"))  measure("malloc 32 B", 32, 0, s, hz);
    if (!strcmp(mode, "all") || !strcmp(mode, "medium")) measure("malloc 4 KiB", 4096, 0, s, hz);
    if (!strcmp(mode, "all") || !strcmp(mode, "large"))  measure("malloc 1 MiB (default)", 1 << 20, 0, s, hz);
    if (!strcmp(mode, "all") || !strcmp(mode, "large-mmap")) {
        mallopt(M_MMAP_THRESHOLD, 512 << 10);                                         /* FIX the threshold: every 1 MiB block is mmap/munmap */
        measure("malloc 1 MiB (forced mmap)", 1 << 20, 0, s, hz);
    }
    if (!strcmp(mode, "all") || !strcmp(mode, "large-heap")) {
        mallopt(M_MMAP_THRESHOLD, 64 << 20); mallopt(M_TRIM_THRESHOLD, 128 << 20);   /* keep 1 MiB blocks on the heap, never trim */
        measure("malloc 1 MiB (heap, no trim)", 1 << 20, 0, s, hz);
    }
    if (!strcmp(mode, "all") || !strcmp(mode, "pool"))   measure("pool 64 B", 64, 1, s, hz);
    return 0;
}

