#define REQS 500
static ssize_t read_n(int fd, char *b, size_t n) { size_t got = 0; while (got < n) { ssize_t r = read(fd, b + got, n - got); if (r <= 0) return r; got += (size_t)r; } return (ssize_t)got; }
static void *server(void *arg) {
    bench_pin(4);
    int ls = socket(AF_INET, SOCK_STREAM, 0), one = 1; setsockopt(ls, SOL_SOCKET, SO_REUSEADDR, &one, sizeof one);
    struct sockaddr_in a = { .sin_family = AF_INET, .sin_port = htons(40003), .sin_addr.s_addr = htonl(INADDR_LOOPBACK) };
    bind(ls, (struct sockaddr *)&a, sizeof a); listen(ls, 1);
    int fd = accept(ls, NULL, NULL); char buf[16];
    for (int i = 0; i < REQS; i++) { if (read_n(fd, buf, 16) <= 0) break; (void)!write(fd, buf, 16); }   /* 16-byte request -> 16-byte reply */
    close(fd); close(ls); (void)arg; return NULL;
}
int main(int argc, char **argv) {
    int nodelay = argc > 1 && !strcmp(argv[1], "nodelay");
    pthread_t th; pthread_create(&th, NULL, server, NULL); usleep(20000);
    bench_pin(2);
    int fd = socket(AF_INET, SOCK_STREAM, 0);
    struct sockaddr_in a = { .sin_family = AF_INET, .sin_port = htons(40003), .sin_addr.s_addr = htonl(INADDR_LOOPBACK) };
    if (connect(fd, (struct sockaddr *)&a, sizeof a)) { perror("connect"); return 1; }
    if (nodelay) { int one = 1; setsockopt(fd, IPPROTO_TCP, TCP_NODELAY, &one, sizeof one); }
    uint64_t *s = malloc(REQS * sizeof *s); char hdr[4] = "HDR!", body[12] = "0123456789ab", reply[16];
    for (int i = 0; i < REQS; i++) {
        uint64_t t0 = bench_ns();
        (void)!write(fd, hdr, 4); (void)!write(fd, body, 12);   /* the classic write-write-read pattern */
        read_n(fd, reply, 16);
        s[i] = bench_ns() - t0;
    }
    pthread_join(th, NULL);
    bench_stats st = bench_compute(s, REQS);
    bench_print_header("request ns"); bench_print(nodelay ? "TCP_NODELAY" : "default (Nagle)", &st);
    long slow = 0; for (int i = 0; i < REQS; i++) slow += s[i] > 1000000; printf("requests slower than 1 ms: %ld of %d\n", slow, REQS);
    return 0;
}

#include "../tools/bench.h"
#include <arpa/inet.h>
#include <errno.h>
#include <pthread.h>
#include <sys/socket.h>
#include <linux/net_tstamp.h>
#include <unistd.h>
#define PKTS 20000
static uint64_t realtime_ns(void) { struct timespec ts; clock_gettime(CLOCK_REALTIME, &ts); return (uint64_t)ts.tv_sec * 1000000000ull + ts.tv_nsec; }
static void *sender(void *arg) {
    bench_pin(4);
    int fd = socket(AF_INET, SOCK_DGRAM, 0);
    struct sockaddr_in dst = { .sin_family = AF_INET, .sin_port = htons(40004), .sin_addr.s_addr = htonl(INADDR_LOOPBACK) };
    for (int i = 0; i < PKTS; i++) { uint64_t t = realtime_ns(); sendto(fd, &t, sizeof t, 0, (struct sockaddr *)&dst, sizeof dst); usleep(50); }
    (void)arg; return NULL;
}
int main(int argc, char **argv) {
    int spin = argc > 1 && !strcmp(argv[1], "spin");
    bench_pin(2);
    int fd = socket(AF_INET, SOCK_DGRAM, 0), on = 1;
    struct sockaddr_in a = { .sin_family = AF_INET, .sin_port = htons(40004), .sin_addr.s_addr = htonl(INADDR_LOOPBACK) };
    if (bind(fd, (struct sockaddr *)&a, sizeof a)) { perror("bind"); return 1; }
    if (setsockopt(fd, SOL_SOCKET, SO_TIMESTAMPNS, &on, sizeof on)) { perror("SO_TIMESTAMPNS"); return 1; }
    pthread_t th; pthread_create(&th, NULL, sender, NULL);
    uint64_t *send2kern = malloc(PKTS * 8), *kern2user = malloc(PKTS * 8); int n = 0;
    for (int i = 0; i < PKTS; i++) {
        uint64_t payload; char cbuf[256]; struct iovec iov = { &payload, sizeof payload };
        struct msghdr msg = { .msg_iov = &iov, .msg_iovlen = 1, .msg_control = cbuf, .msg_controllen = sizeof cbuf };
        ssize_t r;
        if (spin) { while ((r = recvmsg(fd, &msg, MSG_DONTWAIT)) < 0 && errno == EAGAIN) {} } else r = recvmsg(fd, &msg, 0);
        uint64_t now = realtime_ns(); if (r < 0) break;
        for (struct cmsghdr *c = CMSG_FIRSTHDR(&msg); c; c = CMSG_NXTHDR(&msg, c))
            if (c->cmsg_level == SOL_SOCKET && c->cmsg_type == SO_TIMESTAMPNS) {
                struct timespec *ts = (struct timespec *)CMSG_DATA(c); uint64_t k = (uint64_t)ts->tv_sec * 1000000000ull + ts->tv_nsec;
                send2kern[n] = k - payload; kern2user[n] = now - k; n++;
            }
    }
    pthread_join(th, NULL);
    bench_stats a1 = bench_compute(send2kern + 500, n - 500), a2 = bench_compute(kern2user + 500, n - 500);
    printf("receiver: %s   (%d packets, 50 us apart)\n", spin ? "busy-poll (MSG_DONTWAIT loop)" : "blocking recvmsg", n);
    bench_print_header("ns"); bench_print("send -> kernel rx stamp", &a1); bench_print("kernel stamp -> user", &a2);
    return 0;
}

