#include <arm_sve.h>
#endif
__attribute__((noinline)) void vadd(float *c, const float *a, const float *b, long n) { for (long i = 0; i < n; i++) c[i] = a[i] + b[i]; }
__attribute__((noinline)) long isum(const int *a, long n) { long s = 0; for (long i = 0; i < n; i++) s += a[i]; return s; }
__attribute__((noinline)) float fmax_(const float *a, long n) { float m = a[0]; for (long i = 1; i < n; i++) m = a[i] > m ? a[i] : m; return m; }
int main(int argc, char **argv) {
    long n = argc > 1 ? atol(argv[1]) : 1003;                     /* deliberately NOT a multiple of any vector length */
    float *a = malloc(n * 4), *b = malloc(n * 4), *c = malloc(n * 4); int *v = malloc(n * 4);
    for (long i = 0; i < n; i++) { a[i] = (float)i; b[i] = (float)(2 * i); v[i] = (int)(i % 7) - 3; }
    vadd(c, a, b, n);
    long bad = 0; for (long i = 0; i < n; i++) bad += (c[i] != 3.0f * (float)i);
    long s = isum(v, n), expect = 0; for (long i = 0; i < n; i++) expect += (i % 7) - 3;
    float m = fmax_(a, n);
#ifdef __ARM_FEATURE_SVE
    printf("SVE build : VL=%4llu bits (%2llu f32 lanes) | vadd mismatches=%ld | isum=%ld (%s) | fmax=%.0f (%s)\n",
           (unsigned long long)svcntb() * 8, (unsigned long long)svcntw(), bad, s, s == expect ? "ok" : "WRONG", (double)m, m == (float)(n - 1) ? "ok" : "WRONG");
#else
    printf("NEON build: VL= 128 bits ( 4 f32 lanes) | vadd mismatches=%ld | isum=%ld (%s) | fmax=%.0f (%s)\n",
           bad, s, s == expect ? "ok" : "WRONG", (double)m, m == (float)(n - 1) ? "ok" : "WRONG");
#endif
    return bad != 0 || s != expect;
}

