#include <stdio.h>
#include <stdlib.h>
#include <sys/auxv.h>
#include <asm/hwcap.h>
#include <arm_neon.h>
#include <arm_sve.h>          /* usable at file scope without +sve; intrinsics allowed inside target("sve") functions */
/* Two implementations of the same kernel. The SVE one is compiled with a per-function target attribute,
 * so this TU stays a plain armv8-a build: the SVE instructions exist in the binary but run only if chosen. */
__attribute__((noinline)) static float dot_neon(const float *a, const float *b, long n) {
    float32x4_t acc = vdupq_n_f32(0); long i = 0;
    for (; i + 4 <= n; i += 4) acc = vfmaq_f32(acc, vld1q_f32(a + i), vld1q_f32(b + i));
    float s = vaddvq_f32(acc); for (; i < n; i++) s += a[i] * b[i]; return s;
}
__attribute__((noinline, target("sve"))) static float dot_sve(const float *a, const float *b, long n) {
    svfloat32_t acc = svdup_f32(0);
    for (long i = 0; i < n; i += svcntw()) { svbool_t pg = svwhilelt_b32(i, n); acc = svmla_f32_x(pg, acc, svld1(pg, a + i), svld1(pg, b + i)); }
    return svaddv_f32(svptrue_b32(), acc);
}
/* Option A: an ifunc. glibc calls the resolver once at load time; on AArch64 it receives hwcap as its argument. */
typedef float (*dot_fn)(const float *, const float *, long);
static dot_fn resolve_dot(unsigned long hwcap) { return (hwcap & HWCAP_SVE) ? dot_sve : dot_neon; }
float dot(const float *a, const float *b, long n) __attribute__((ifunc("resolve_dot")));
/* Option B: an explicit function pointer chosen at startup (portable, testable, no loader magic). */
static dot_fn g_dot;
int main(int argc, char **argv) {
    long n = argc > 1 ? atol(argv[1]) : 1001; unsigned long hw = getauxval(AT_HWCAP);
    g_dot = (hw & HWCAP_SVE) ? dot_sve : dot_neon;
    float *a = malloc(n * 4), *b = malloc(n * 4); double ref = 0;
    for (long i = 0; i < n; i++) { a[i] = (float)(i % 13) * 0.5f; b[i] = (float)(i % 7) * 0.25f + 1.0f; ref += (double)a[i] * b[i]; }
    float r_ifunc = dot(a, b, n), r_ptr = g_dot(a, b, n), r_neon = dot_neon(a, b, n);
    printf("HWCAP sve=%d -> chosen: %s | ifunc=%.3f ptr=%.3f neon=%.3f ref=%.3f | max abs diff=%.3g\n",
           !!(hw & HWCAP_SVE), (hw & HWCAP_SVE) ? "dot_sve" : "dot_neon", r_ifunc, r_ptr, r_neon, ref,
           (double)(r_ifunc - (float)ref) > 0 ? (double)(r_ifunc - (float)ref) : -(double)(r_ifunc - (float)ref));
    return 0;
}

#include <stdio.h>
#include <sys/auxv.h>
#include <asm/hwcap.h>
#include <arm_sme.h>
/* __arm_locally_streaming: the compiler enters streaming SVE mode on entry and leaves on return (smstart/smstop). */
__arm_locally_streaming static unsigned long streaming_vl_bits(void) { return svcntsb() * 8; }
/* ZA is the matrix accumulator: N x N bytes where N = SVL in bytes. One outer product accumulates a tile. */
__arm_locally_streaming __arm_new("za") static float outer_trace(const float *x, const float *y) {
    svbool_t pg = svptrue_b32();
    svfloat32_t vx = svld1(pg, x), vy = svld1(pg, y);
    svzero_za();
    svmopa_za32_f32_m(0, pg, pg, vx, vy);                  /* ZA0 += x (col) * y (row): a full tile in ONE instruction */
    float trace = 0; unsigned n = svcntsw();
    for (unsigned r = 0; r < n; r++) {                     /* read row r of tile 0, pick element r */
        svfloat32_t row = svread_hor_za32_f32_m(svdup_f32(0), pg, 0, r);
        float tmp[64]; svst1(pg, tmp, row); trace += tmp[r];
    }
    return trace;
}
int main(void) {
    unsigned long h2 = getauxval(AT_HWCAP2);
    if (!(h2 & HWCAP2_SME)) { printf("no SME on this CPU (HWCAP2_SME clear); nothing to run\n"); return 0; }
    float x[64], y[64]; for (int i = 0; i < 64; i++) { x[i] = (float)(i + 1); y[i] = 1.0f; }
    unsigned long svl = streaming_vl_bits();
    printf("SME present. streaming VL = %lu bits -> ZA tile is %lu x %lu f32\n", svl, svl / 32, svl / 32);
    printf("trace of outer(x, ones) over the tile = %.0f (expected sum 1..%lu = %lu)\n", (double)outer_trace(x, y), svl / 32, (svl / 32) * (svl / 32 + 1) / 2);
    return 0;
}

