func.func @tensor_world(%t: tensor<4xf32>, %v: f32) -> tensor<4xf32> {
  %c1 = arith.constant 1 : index
  %t2 = tensor.insert %v into %t[%c1] : tensor<4xf32>
  return %t2 : tensor<4xf32>
}

// BUFFER semantics: memrefs are pointers + shape + strides. "store" mutates memory.
func.func @memref_world(%m: memref<4xf32>, %v: f32) {
  %c1 = arith.constant 1 : index
  memref.store %v, %m[%c1] : memref<4xf32>
  return
}

// A memref is a VIEW: a subview of every other column has a non-trivial layout.
func.func @views(%m: memref<8x8xf32>) -> memref<4x4xf32, strided<[8, 2], offset: 17>> {
  %s = memref.subview %m[2, 1] [4, 4] [1, 2]
      : memref<8x8xf32> to memref<4x4xf32, strided<[8, 2], offset: 17>>
  return %s : memref<4x4xf32, strided<[8, 2], offset: 17>>
}

// VECTOR types: what ends up in SIMD registers. [4] is fixed (NEON-sized for f32),
// [[4]] is SCALABLE: 4 x vscale lanes, the SVE model (lab 05_aarch64).
func.func @vectors(%a: vector<4xf32>, %b: vector<[4]xf32>) -> (vector<4xf32>, vector<[4]xf32>) {
  %a2 = arith.addf %a, %a : vector<4xf32>
  %b2 = arith.addf %b, %b : vector<[4]xf32>
  return %a2, %b2 : vector<4xf32>, vector<[4]xf32>
}

// Constant folding is free once you have values instead of memory:
func.func @fold_me() -> i32 {
  %a = arith.constant 6 : i32
  %b = arith.constant 7 : i32
  %c = arith.muli %a, %b : i32
  return %c : i32
}

func.func @type_mismatch(%a: f32, %b: f64) -> f32 {
  // expected-note @-1 {{prior use here}}
  // expected-error @+1 {{use of value '%b' expects different type than prior uses: 'f32' vs 'f64'}}
  %s = arith.addf %a, %b : f32
  return %s : f32
}

// -----
// == case B: SSA dominance (use before def)
func.func @dominance(%c: i1) -> i32 {
  cf.cond_br %c, ^bb1, ^bb2
^bb1:
  // expected-note @+1 {{operand defined here}}
  %x = arith.constant 1 : i32
  cf.br ^bb2
^bb2:
  // expected-error @+1 {{operand #0 does not dominate this use}}
  return %x : i32
}

// -----
// == case C: op-specific verifier (linalg)
func.func @bad_matmul(%a: tensor<4x8xf32>, %b: tensor<16x4xf32>, %c: tensor<4x4xf32>) -> tensor<4x4xf32> {
  // expected-error @+1 {{inferred input/output operand #1 has shape's dimension #0 to be 8, but found 16}}
  %r = linalg.matmul ins(%a, %b : tensor<4x8xf32>, tensor<16x4xf32>) outs(%c : tensor<4x4xf32>) -> tensor<4x4xf32>
  return %r : tensor<4x4xf32>
}

// -----
// == case D: region terminator
func.func @no_yield(%n: index) {
  %c0 = arith.constant 0 : index
  %c1 = arith.constant 1 : index
  // expected-note @+2 {{region branch point}}
  // expected-error @+1 {{region branch point has 0 operands, but region successor needs 1 inputs}}
  %r = scf.for %i = %c0 to %n step %c1 iter_args(%acc = %c0) -> (index) {
    %s = arith.addi %acc, %i : index
  }
  return
}

func.func @sum_relu(%x: memref<?xf32>) -> f32 {
  %c0 = arith.constant 0 : index
  %c1 = arith.constant 1 : index
  %zero = arith.constant 0.0 : f32
  %n = memref.dim %x, %c0 : memref<?xf32>
  %r = scf.for %i = %c0 to %n step %c1 iter_args(%acc = %zero) -> (f32) {
    %v = memref.load %x[%i] : memref<?xf32>
    %relu = arith.maximumf %v, %zero : f32
    %acc2 = arith.addf %acc, %relu : f32
    scf.yield %acc2 : f32
  }
  return %r : f32
}

